questionvariables.text:
/* Radio options: static literal values, sentence displays. Exactly one is true. */
ta1: [[optA, false, "A. Restricting the domain removes the need for the function to pass the vertical line test."],
 [optB, false, "B. Restricting the domain makes the function many-to-many, and a many-to-many relation always has an inverse."],
 [optC, true, "C. Restricting the domain changes the mapping from many-to-one to one-to-one, so each output now comes from only one input."],
 [optD, false, "D. Restricting the domain has no effect on whether an inverse exists."]];
tac1: first(mcq_correct(ta1));
